head.script:
scwin.trigger1_onclick = function(e) {
    var title = "sub" + scwin.cnt;
    var xml = "windowContainer_processMsgFrame_WEFF-796_(WSQ-4141)_sub.xml";
    windowContainer1.createWindow(title, null, xml);
    scwin.cnt++;
};
scwin.trigger3_onclick = function(e) {
    windowContainer1.getFrame("sub1").setSrc("windowContainer_processMsgFrame_WEFF-796_(WSQ-4141)_sub.xml");
};
scwin.getErrorLog = function() {
    var temp = WebSquare.logger.getErrorLog();
    return temp;
    // return temp.indexOf("error문구");
    // return temp.indexOf("error");
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById($p.id+'trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById($p.id+'windowContainer1_subWindow0_wframe_trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById($p.id+'trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById($p.id+'windowContainer1_subWindow0_wframe_trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.getErrorLog() == ''", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.cnt = 1;
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
